1	/**
2	 * Scoped to this atom's own contract per testing.md: given href/no href, does it render the
3	 * right element type; does aria-checked/tabIndex track isSelected/isFocusable; does the passed
4	 * imageUrl reach the DOM as the swatch's background-image fill; and — the regression guard —
5	 * does the swatch box's background-colour stay pinned to the recipe's own token declaration
6	 * regardless of the colour `name`, rather than picking up a raw CSS-colour-keyword the way base
7	 * SFCC's own `renderDefaultVariationAttribute` does (`backgroundColor={name.toLowerCase()}`) —
8	 * see index.tsx's own comment for the three reasons this atom deliberately does not replicate
9	 * that.
10	 *
11	 * Every render needs three wrappers, not just the router:
12	 *   - `ChakraProvider theme={theme}` (the real theme, not Chakra's default) — without it,
13	 *     `useMultiStyleConfig('ZimmColourSwatch', ...)` resolves against a theme with no such key
14	 *     registered and silently returns `{}` for both parts, which would make every assertion below
15	 *     pass vacuously against an unstyled node rather than against this recipe. Same reasoning as
16	 *     zimmProductMeta/index.test.tsx's own "resolves its recipe under a ChakraProvider" test.
17	 *   - `MemoryRouter` — this atom can render a react-router `Link`, which throws outside one.
18	 *   - `ZimmTokensGlobal` — without a `:root` definition for the `--zimm-*` variables the recipe
19	 *     references, a resolved-value assertion has nothing to distinguish "correct" from
20	 *     "regressed" (see the regression-guard test below).
21	 *
22	 * `getComputedStyle`, not `element.style`: Chakra resolves `__css` through Emotion, which applies
23	 * a generated class rather than an inline `style` attribute, so the inline `style` property never
24	 * reflects the resolved value — matching how every other Chakra-styles assertion in this codebase
25	 * reads a resolved value (zimmProductMeta/index.test.tsx, zimmProductPrice/index.test.tsx,
26	 * theme/index.test.tsx).
27	 *
28	 * One further, load-bearing wrinkle specific to a `var(--zimm-*)`-driven recipe (as opposed to a
29	 * bare Chakra-scale key, which those other files' assertions read): confirmed directly against
30	 * this file, jsdom's `getComputedStyle` does not substitute a custom property's value — it
31	 * echoes back the literal declaration text (`"var(--zimm-color-bg-02)"`), never the
32	 * resolved hex/rgb. That is actually what makes the regression guard below simple rather than
33	 * impossible: it asserts on that literal, unsubstituted declaration string, which is exactly
34	 * "which value authored this" — variable reference vs. some other literal. A real browser (Chrome
35	 * driving the Storybook `play` in index.stories.tsx) does perform the substitution; this file
36	 * doesn't need it to, because the literal declaration is the more direct thing to assert on.
37	 *
38	 * No ZimmIcon anywhere in this component, so no need for the ZimmIcon-throws-under-Vitest mock
39	 * documented in testing.md.
40	 */
41	import React from 'react';
42	import { describe, test, expect } from 'vitest';
43	import { render, screen } from '@testing-library/react';
44	import { ChakraProvider } from '@chakra-ui/react';
45	import { MemoryRouter } from 'react-router-dom';
46	import theme from 'app/theme';
47	import { ZimmTokensGlobal } from 'app/theme/zimmTokensGlobal';
48	import { ZimmColourSwatch } from './index';
49	
50	const IMAGE_URL = 'https://picsum.photos/seed/zimmermann-bay-blue/400/600';
51	
52	const renderSwatch = (overrides: Partial<React.ComponentProps<typeof ZimmColourSwatch>> = {}) =>
53	  render(
54	    <ChakraProvider theme={theme}>
55	      <MemoryRouter>
56	        <ZimmTokensGlobal />
57	        <ZimmColourSwatch name="Bay Blue" imageUrl={IMAGE_URL} isSelected={false} isFocusable={true} {...overrides} />
58	      </MemoryRouter>
59	    </ChakraProvider>,
60	  );
61	
62	describe('ZimmColourSwatch', () => {
63	  test('renders an anchor carrying the given href when href is present', () => {
64	    renderSwatch({ href: '/womens/dresses/natura-mini-dress/8637DS241.html?color=BAYBL' });
65	    const swatch = screen.getByRole('radio');
66	    expect(swatch.tagName).toBe('A');
67	    expect(swatch).toHaveAttribute('href', '/womens/dresses/natura-mini-dress/8637DS241.html?color=BAYBL');
68	  });
69	
70	  test('renders a non-anchor element when href is absent', () => {
71	    renderSwatch({ href: undefined });
72	    const swatch = screen.getByRole('radio');
73	    expect(swatch.tagName).not.toBe('A');
74	  });
75	
76	  test('isSelected=true sets aria-checked="true"', () => {
77	    renderSwatch({ isSelected: true });
78	    expect(screen.getByRole('radio')).toHaveAttribute('aria-checked', 'true');
79	  });
80	
81	  test('isSelected=false sets aria-checked="false"', () => {
82	    renderSwatch({ isSelected: false });
83	    expect(screen.getByRole('radio')).toHaveAttribute('aria-checked', 'false');
84	  });
85	
86	  test('isFocusable=true sets tabIndex to 0', () => {
87	    renderSwatch({ isFocusable: true });
88	    expect(screen.getByRole('radio')).toHaveAttribute('tabindex', '0');
89	  });
90	
91	  test('isFocusable=false sets tabIndex to -1', () => {
92	    renderSwatch({ isFocusable: false });
93	    expect(screen.getByRole('radio')).toHaveAttribute('tabindex', '-1');
94	  });
95	
96	  // Regression guard for the _focusVisible `position: relative` + `zIndex: 1` fix in
97	  // zimmColourSwatch.css.ts (SFCC-91) — without it, a focused swatch's outline ring has its
98	  // right edge painted over by the next zero-gap sibling. Only `position`/`zIndex` are
99	  // asserted here, not the rest of that `_focusVisible` block (`outline`/`outlineOffset`):
100	  // jsdom's `getComputedStyle` does reflect `position`/`zIndex` correctly once a real
101	  // `.focus()` call happens, but `outline`/`outlineOffset` themselves are a separate,
102	  // pre-existing jsdom limitation — unrelated to this fix — that this test does not attempt
103	  // to work around.
104	  test('focus-visible position/zIndex are not hidden by the next sibling swatch (regression guard, SFCC-91)', () => {
105	    const { container } = render(
106	      <ChakraProvider theme={theme}>
107	        <MemoryRouter>
108	          <ZimmTokensGlobal />
109	          <div style={{ display: 'flex', gap: 0 }}>
110	            <ZimmColourSwatch name="Bay Blue" imageUrl={IMAGE_URL} isSelected={false} isFocusable={true} />
111	            <ZimmColourSwatch name="Ivory" imageUrl={IMAGE_URL} isSelected={false} isFocusable={true} />
112	          </div>
113	        </MemoryRouter>
114	      </ChakraProvider>,
115	    );
116	    const first = container.querySelectorAll('[data-testid="colour-swatch"]')[0] as HTMLElement;
117	    first.focus();
118	    const cs = getComputedStyle(first);
119	    expect(cs.position).toBe('relative');
120	    expect(cs.zIndex).toBe('1');
121	  });
122	
123	  test('renders the passed imageUrl as the swatch fill background-image', () => {
124	    renderSwatch({ imageUrl: IMAGE_URL });
125	    const swatch = screen.getByRole('radio');
126	    const imageEl = swatch.firstElementChild as HTMLElement;
127	    expect(getComputedStyle(imageEl).backgroundImage).toContain(IMAGE_URL);
128	  });
129	
130	  test('does not set a raw CSS-colour-keyword backgroundColor from the colour name (regression guard)', () => {
131	    renderSwatch({ name: 'Bay Blue' });
132	    const swatch = screen.getByRole('radio');
133	    // The recipe's own unconditional declaration — see the file-level comment above for why this
134	    // literal, unsubstituted form is what jsdom actually reports. A regression re-adding
135	    // `backgroundColor={name.toLowerCase()}` as an extra prop on this element would overwrite this
136	    // key in the final merged style object (Chakra assigns component style props after `__css`),
137	    // so this would read the literal "bay blue" instead — proven by an actual mutation run, not
138	    // assumed; see the PR body / step report for that run's before/after output.
139	    expect(getComputedStyle(swatch).backgroundColor).toBe('var(--zimm-color-bg-02)');
140	  });
141	});
