import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { MemoryRouter } from 'react-router-dom';
import { expect, within } from 'storybook/test';
import { ZimmColourSwatch } from '.';

/** Placeholder swatch fill — doesn't need to resolve to a real product, just a working image URL. */
const SAMPLE_IMAGE_URL = 'https://picsum.photos/seed/zimmermann-bay-blue/400/600';

const meta: Meta<typeof ZimmColourSwatch> = {
  title: 'Commerce/ZimmColourSwatch',
  component: ZimmColourSwatch,
  argTypes: {
    name: { control: 'text' },
    imageUrl: { control: 'text' },
    href: { control: 'text' },
    isSelected: { control: 'boolean' },
    isFocusable: { control: 'boolean' },
  },
  decorators: [
    // .storybook/preview.tsx (Tier 1) supplies Chakra + Intl globally but no Router — this atom
    // can render a react-router `Link`, which throws outside one. Local decorator, same reason
    // staticProductHeader.stories.tsx adds one for its own base-`Breadcrumb` links.
    (Story: React.ComponentType) => (
      <MemoryRouter>
        <Story />
      </MemoryRouter>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof ZimmColourSwatch>;

export const Default: Story = {
  args: {
    name: 'Bay Blue',
    imageUrl: SAMPLE_IMAGE_URL,
    href: '/womens/dresses/natura-mini-dress/8637DS241.html?color=BAYBL',
    isSelected: false,
    isFocusable: true,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const swatch = canvas.getByRole('radio', { name: 'Bay Blue' });
    await expect(swatch).toHaveAttribute('aria-checked', 'false');
    await expect(swatch.tagName).toBe('A');
    await expect(swatch).toHaveAttribute('href', '/womens/dresses/natura-mini-dress/8637DS241.html?color=BAYBL');
  },
};

export const Selected: Story = {
  args: {
    ...Default.args,
    isSelected: true,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByRole('radio', { name: 'Bay Blue' })).toHaveAttribute('aria-checked', 'true');
  },
};

export const WithoutLink: Story = {
  name: 'Without a link — quick-view-modal path',
  args: {
    name: 'Ivory',
    imageUrl: SAMPLE_IMAGE_URL,
    href: undefined,
    isSelected: false,
    isFocusable: true,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const swatch = canvas.getByTestId('colour-swatch');
    // No `href` means no anchor at all — a plain chakra.span instead.
    await expect(swatch.tagName).not.toBe('A');
  },
};

